    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	    private final ReservationNotifications notifications;
    20	
    21	    public ReservationService(
    22	            Rooms rooms,
    23	            ReservationStore store,
    24	            PriceCalculator priceCalculator,
    25	            EmailSender emailSender,
    26	            ReservationNotifications notifications) {
    27	        this.rooms = rooms;
    28	        this.store = store;
    29	        this.priceCalculator = priceCalculator;
    30	        this.emailSender = emailSender;
    31	        this.notifications = notifications;
    32	    }
    33	
    34	    public synchronized Reservation create(NewReservation request) {
    35	        if (!request.checkOut().isAfter(request.checkIn())) {
    36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    37	        }
    38	        if (request.guests() < 1) {
    39	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    40	        }
    41	        Room room = rooms.find(request.roomNumber())
    42	                .orElseThrow(() -> new HotelException(
    43	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    44	        if (request.guests() > room.capacity()) {
    45	            throw new HotelException(
    46	                    ErrorCode.CAPACITY_EXCEEDED,
    47	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    48	        }
    49	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    50	            throw new HotelException(
    51	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    52	        }
    53	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    54	        return store.add(request, price);
    55	    }
    56	
    57	    public Reservation find(long reservationId) {
    58	        return store.find(reservationId)
    59	                .orElseThrow(() -> new HotelException(
    60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    61	    }
    62	
    63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    64	    public synchronized Reservation confirm(long reservationId) {
    65	        Reservation reservation = find(reservationId);
    66	        if (reservation.status() != ReservationStatus.PENDING) {
    67	            throw notAllowed(reservation, "confirm");
    68	        }
    69	        reservation.confirmPayment();
    70	        store.update(reservation);
    71	        Room room = roomOf(reservation);
    72	        ReservationReceipt receipt = new ReservationReceipt(reservation, room);
    73	        emailSender.send(
    74	                reservation.guest().email(),
    75	                "Reserva confirmada - " + HOTEL_NAME,
    76	                confirmationEmailBody(reservation, receipt));
    77	        notifications.notifyConfirmed(reservation, room);
    78	        return reservation;
    79	    }
    80	
    81	    /**
    82	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    83	     * reservation was never paid, so nothing comes back).
    84	     */
    85	    public synchronized Reservation cancel(long reservationId) {
    86	        Reservation reservation = find(reservationId);
    87	        if (reservation.status() != ReservationStatus.PENDING
    88	                && reservation.status() != ReservationStatus.CONFIRMED) {
    89	            throw notAllowed(reservation, "cancel");
    90	        }
    91	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    92	        BigDecimal refund = switch (reservation.ratePlan()) {
    93	            case STANDARD -> reservation.amountPaid();
    94	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    95	        };
    96	        reservation.cancel(refund);
    97	        store.update(reservation);
    98	        if (wasConfirmed) {
    99	            notifications.notifyCancelled(reservation, roomOf(reservation));
   100	        }
   101	        return reservation;
   102	    }
   103	
   104	    public synchronized Reservation checkIn(long reservationId) {
   105	        Reservation reservation = find(reservationId);
   106	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   107	            throw notAllowed(reservation, "check in");
   108	        }
   109	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   110	        store.update(reservation);
   111	        return reservation;
   112	    }
   113	
   114	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   115	    public synchronized ReservationReceipt checkOut(long reservationId) {
   116	        Reservation reservation = find(reservationId);
   117	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   118	            throw notAllowed(reservation, "check out");
   119	        }
   120	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   121	        store.update(reservation);
   122	        return new ReservationReceipt(reservation, roomOf(reservation));
   123	    }
   124	
   125	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   126	    public ReservationReceipt receiptCopy(long reservationId) {
   127	        Reservation reservation = find(reservationId);
   128	        if (!reservation.isPaid()) {
   129	            throw notAllowed(reservation, "issue a receipt for");
   130	        }
   131	        return new ReservationReceipt(reservation, roomOf(reservation));
   132	    }
   133	
   134	    private Room roomOf(Reservation reservation) {
   135	        return rooms.find(reservation.roomNumber()).orElseThrow();
   136	    }
   137	
   138	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   139	        return "Olá, " + reservation.guest().name() + "!\n\n"
   140	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   141	                + receipt.text() + "\n"
   142	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   143	                + "Até breve!\n";
   144	    }
   145	
   146	    private static HotelException notAllowed(Reservation reservation, String operation) {
   147	        return new HotelException(
   148	                ErrorCode.OPERATION_NOT_ALLOWED,
   149	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   150	    }
   151	}
